def solve_cvrp(instance):
    # Minimal, deterministic CVRP solver with constructive, repair, and local-search ideas.
    if instance is None:
        return []
    customers = instance.get('customers', [])
    depot = instance.get('depot', None)
    capacity = instance.get('vehicle_capacity', 0)

    if capacity <= 0 or not customers:
        return []

    # Deterministic ordering: by id ascending
    customers_sorted = sorted(customers, key=lambda c: c.get('id', 0))

    # Map id -> customer
    unvisited = {c['id']: c for c in customers_sorted}

    routes = []
    current_route = []
    current_load = 0

    # Helper to add to route
    def add_to_route(cid, customer_obj):
        nonlocal current_route, current_load
        current_route.append(cid)
        current_load += customer_obj.get('demand', 0)

    # Construct routes deterministically
    for cid in sorted(unvisited.keys()):
        cust = unvisited[cid]
        demand = cust.get('demand', 0)

        if demand > capacity:
            # skip in this deterministic baseline (invalid in practice)
            continue

        if current_load + demand <= capacity:
            add_to_route(cid, cust)
        else:
            if current_route:
                routes.append(current_route)
            current_route = [cid]
            current_load = demand

    if current_route:
        routes.append(current_route)

    # Repair: try to merge adjacent routes if fits
    i = len(routes) - 1
    while i > 0:
        r_prev = routes[i-1]
        r_cur = routes[i]
        sum_prev = sum(unvisited[c]['demand'] for c in r_prev)
        sum_cur = sum(unvisited[c]['demand'] for c in r_cur)
        if sum_prev + sum_cur <= capacity:
            routes[i-1] = r_prev + r_cur
            del routes[i]
            i -= 1
        else:
            i -= 1

    # Local-search: intra-route adjacent swaps to reduce bias (deterministic)
    for r_idx in range(len(routes)):
        route = routes[r_idx]
        improved = True
        while improved:
            improved = False
            for j in range(len(route) - 1):
                a, b = route[j], route[j+1]
                # deterministic swap: only if a > b
                if a > b:
                    route[j], route[j+1] = b, a
                    improved = True
            if improved:
                routes[r_idx] = route

    # Ensure every customer present exactly once
    seen = set()
    for r in routes:
        for cid in r:
            seen.add(cid)
    missing = [c['id'] for c in customers if c['id'] not in seen]
    for mid in missing:
        routes.append([mid])

    return routes

